import {esc,icon} from './ui.mjs';

const routeMap={projects:'projects?scope=account',tasks:'tasks?scope=account',agent:'tasks?scope=account&view=agent',results:'assets?scope=account',usage:'account?view=usage',membership:'membership?scope=account',help:'help?scope=account'};
export function onlineWorkspaceHref(view,params={}){const route=routeMap[view]||'home';return '#'+route+Object.entries(params).map(([key,value])=>'&'+encodeURIComponent(key)+'='+encodeURIComponent(value)).join('');}
let activeWorkspace=null;
export const onlineWorkspaceConfirmLeave=()=>activeWorkspace?.confirmLeave()??Promise.resolve(true);
export const onlineWorkspaceSessionChanged=user=>activeWorkspace?.sessionChanged(user);
export const onlineWorkspaceHasWork=()=>!!activeWorkspace?.hasWork();
export function disposeOnlineWorkspace(){activeWorkspace?.dispose();activeWorkspace=null;}
export function onlineWorkspaceRouteGuard(target){return activeWorkspace?.guard(target)??true;}
if(typeof window!=='undefined')window.addEventListener('beforeunload',event=>{if(onlineWorkspaceHasWork()){event.preventDefault();event.returnValue='';}});
export async function mountOnlineWorkspace(root,requestedView,ctx={},params=new URLSearchParams()){
 disposeOnlineWorkspace();
 let alive=true,user=null,cap={},projects=[],files=[],jobs=[],results=[],view=routeMap[requestedView]?requestedView:'projects',timer,busy=false,allowLeave=false,resultRequest=0;
 const controllers=new Set(),formSnapshots=new WeakMap();
 const $=selector=>root.querySelector(selector),$all=selector=>root.querySelectorAll(selector);
 const date=value=>new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
 const statuses={queued:'排队中',running:'处理中',completed:'已完成',failed:'失败',cancelled:'已取消'};
 const notify=message=>{if(!alive)return;const node=$('#online-notice');if(node)node.textContent=message;ctx.notify?.(message);};
 root.classList.add('account-workspace');
 root.innerHTML=`<div id="online-notice" role="status" aria-live="polite"></div><div id="online-mode-actions"></div><div id="view"><section class="card account-loading">${icon('clock',23)}<p>正在读取账户内容…</p></section></div><dialog id="online-confirm" aria-labelledby="online-confirm-title"><h2 id="online-confirm-title">确认操作</h2><p id="online-confirm-message"></p><div class="actions"><button id="online-confirm-no" type="button">继续当前操作</button><button id="online-confirm-yes" class="primary" type="button">确认继续</button></div></dialog>`;
 function ask(message){const dialog=$('#online-confirm');if(!alive||!dialog||dialog.open)return Promise.resolve(false);$('#online-confirm-message').textContent=message;const previous=document.activeElement;dialog.showModal();return new Promise(resolve=>{const finish=value=>{dialog.close();previous?.focus();resolve(value);};$('#online-confirm-no').onclick=()=>finish(false);$('#online-confirm-yes').onclick=()=>finish(true);dialog.oncancel=event=>{event.preventDefault();finish(false);};});}
 function formSnapshot(form){return JSON.stringify([...form.elements].filter(element=>['INPUT','SELECT','TEXTAREA'].includes(element.tagName)).map(element=>element.type==='file'?[...element.files].map(file=>[file.name,file.size,file.lastModified]):element.type==='checkbox'?element.checked:element.value));}
 function rememberForms(force=false){$all('#view form').forEach(form=>{if(force||!formSnapshots.has(form))formSnapshots.set(form,formSnapshot(form));});}
 function dirty(){return [...$all('#view form')].some(form=>formSnapshots.has(form)&&formSnapshot(form)!==formSnapshots.get(form));}
 function go(next,extra={}){allowLeave=true;const href=onlineWorkspaceHref(next,extra);if(ctx.navigate)ctx.navigate(href);else location.hash=href;}
 const instance={hasWork:()=>busy||dirty(),async confirmLeave(){if(busy){notify('当前操作正在保存，请稍候。');return false;}return !dirty()||await ask('当前输入尚未保存，退出后会丢弃这次修改。是否继续？');},sessionChanged(nextUser){if(!user||user.id===nextUser?.id)return;void mountOnlineWorkspace(root,view,ctx,params);},dispose(){alive=false;clearTimeout(timer);controllers.forEach(controller=>controller.abort());observer.disconnect();},guard(target){if(allowLeave){allowLeave=false;return true;}if(busy){notify('当前操作正在保存，请稍候再切换。');return false;}if(!dirty())return true;void ask('当前输入尚未保存，离开后会丢弃这次修改。是否继续？').then(accepted=>{if(accepted&&alive){allowLeave=true;location.hash=target;}});return false;}};
 const observer=new MutationObserver(()=>rememberForms());observer.observe(root,{childList:true,subtree:true});activeWorkspace=instance;
 async function api(path,data){const controller=new AbortController();controllers.add(controller);const timeout=setTimeout(()=>controller.abort(),20000);try{const response=await fetch('/api'+path,{method:data===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),signal:controller.signal});const value=await response.json();if(!alive)throw new DOMException('页面已切换','AbortError');if(!response.ok){if(response.status===401){user=null;clearTimeout(timer);renderLogin();}const error=new Error(value.error||'请求未完成，请稍后重试');error.status=response.status;throw error;}return value;}finally{clearTimeout(timeout);controllers.delete(controller);}}
 function renderLogin(){if(!alive)return;const next='/workspace.html'+location.search+location.hash;$('#online-mode-actions').innerHTML='';$('#view').innerHTML=`<section class="card account-login-required"><span class="account-empty-symbol">${icon('user',28)}</span><h2>登录后查看账户内容</h2><p>账户项目、文件和任务与当前浏览器的本地草稿分别保存。</p><a class="button" href="/auth.html?mode=login&next=${encodeURIComponent(next)}">登录账户 ${icon('arrow',15)}</a></section>`;ctx.sessionExpired?.();}
 async function refresh(){[projects,files,jobs,results]=await Promise.all(['/projects','/files','/jobs','/results'].map(path=>api(path).then(value=>value.items)));}
 function optionProjects(){return '<option value="">独立任务 / 未归入项目</option>'+projects.map(project=>`<option value="${esc(project.id)}">${esc(project.title)}</option>`).join('');}
 async function render(){if(!alive||!user)return;$('#online-mode-actions').innerHTML=['tasks','agent'].includes(view)?`<div class="account-task-modes"><a class="${view==='tasks'?'active':''}" href="${onlineWorkspaceHref('tasks')}">处理任务</a><a class="${view==='agent'?'active':''}" href="${onlineWorkspaceHref('agent')}">${icon('grid',16)}科研智能助手</a></div>`:'';await renderView();rememberForms();}
 async function poll(){clearTimeout(timer);if(!alive||!user)return;timer=setTimeout(async()=>{if(!alive)return;try{if(!document.hidden&&['tasks','agent'].includes(view)){jobs=(await api('/jobs')).items;renderJobs();}}catch(error){if(alive&&error.name!=='AbortError'&&error.status!==401)notify('任务状态暂时无法更新，将自动重试。');}finally{if(alive&&user)poll();}},5000);}
function resultRows(){return results.length?results.map(r=>`<div class="row"><span><b>${esc(r.title)}</b><br><small class="muted">${esc(r.type)} · ${date(r.created_at)}</small></span><button data-result="${r.id}">打开成果</button></div>`).join(''):'<p class="muted">还没有成果，先上传并解析文件或创建任务。</p>';}
async function renderView(){const target=$('#view');if(view==='projects'){target.innerHTML=`<div class="grid"><section class="card"><h2>新建项目</h2><form id="project-form"><label for="project-title">项目名称</label><input id="project-title" maxlength="200" required><label for="degree">学段</label><select id="degree"><option>专科</option><option selected>本科</option><option>硕士</option><option>博士</option><option>科研人员</option></select><label for="major">专业（可选）</label><input id="major" maxlength="100"><div class="actions"><button class="primary">保存项目</button></div></form></section><section class="card"><h2>上传论文原件</h2><form id="upload-form"><label for="upload-project">所属项目</label><select id="upload-project">${optionProjects()}</select><label for="upload-file">TXT / DOCX / 文本 PDF（最大 2MB）</label><input id="upload-file" type="file" accept=".txt,.docx,.pdf" required><p class="muted">${cap.storage==='aliyun_oss'?'上传会将原件保存到阿里云 OSS 私有目录。':'上传会将原件保存到 PaperKnow 服务器。'}正文解析作为独立后台任务执行。扫描 PDF 暂无 OCR。</p><div class="actions"><button class="primary">上传并解析</button></div></form></section><section class="card"><h2>我的项目</h2>${projects.map(p=>`<div class="row"><span><b>${esc(p.title)}</b><br><small>${esc(p.degree)} · ${esc(p.major)} · ${date(p.updated_at)}</small></span><span class="tag">${files.filter(f=>f.project_id===p.id).length} 份原件</span></div>`).join('')||'<p>尚无项目</p>'}</section><section class="card"><h2>原件列表</h2>${files.map(f=>`<div class="row"><span><b>${esc(f.name)}</b><br><small>${f.bytes} 字节</small></span><a href="/api/files/${f.id}/download">下载原件</a></div>`).join('')||'<p>尚无文件</p>'}</section></div>`;$('#project-form').onsubmit=e=>submit(e,async()=>{await api('/projects',{title:$('#project-title').value,degree:$('#degree').value,major:$('#major').value});const uploadForm=$('#upload-form'),selectedProject=$('#upload-project').value;await refresh();await render();$('#upload-form').replaceWith(uploadForm);$('#upload-project').innerHTML=optionProjects();$('#upload-project').value=selectedProject;notify('项目已保存');});$('#upload-form').onsubmit=e=>submit(e,async()=>{const projectForm=$('#project-form');if(formSnapshot(projectForm)!==formSnapshots.get(projectForm)&&!await ask('新项目表单尚未保存。上传后将进入任务中心，是否继续？'))return;const f=$('#upload-file').files[0];if(!f)throw new Error('请选择论文原件');if(f.size>2*1024*1024)throw new Error('文件最大 2MB');const projectId=$('#upload-project').value;const bytes=new Uint8Array(await f.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const file=await api('/files',{name:f.name,data:btoa(binary),projectId});await api('/jobs',{type:'parse',fileId:file.id,projectId,idempotencyKey:crypto.randomUUID()});rememberForms(true);notify('原件已保存，正文解析已加入队列');go('tasks');});return;}
if(view==='agent'){target.innerHTML=`<div class="grid"><section class="card"><h2>科研智能助手</h2><p class="muted">读取所选材料、整理研究思路、提炼问题与修改建议。使用当前后台模型执行，结果需要人工核对。</p><form id="agent-form"><label for="agent-project">所属项目</label><select id="agent-project">${optionProjects()}</select><label for="agent-text">你希望完成什么？</label><textarea id="agent-text" maxlength="6000" required placeholder="例如：阅读所选开题报告，整理研究目标、方法与待完善的问题，并注明依据。"></textarea><label for="agent-materials">选择原件（可选，最多 5 份）</label><select id="agent-materials" multiple size="4">${files.map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('')}</select><p class="muted">可以不选文件，仅处理你输入的任务。所选原件正文总计最多 40,000 字符；按住 Ctrl 或 Command 可多选。请先在“我的项目 · 账户内容”上传原件。</p><label for="agent-requirements">补充要求（可选）</label><textarea id="agent-requirements" maxlength="2000"></textarea><p class="muted">任务和所选材料内容将发送至 ${esc(cap.aiProvider||'当前配置的模型服务')}。当前支持材料读取与文本统计；不执行系统命令，不进行全网检索。</p><div class="actions"><button class="primary" id="agent-submit" ${cap.agent?'':'disabled'}>${cap.agent?'开始智能任务':'智能任务未启用'}</button></div></form></section><section class="card"><h2>任务进度</h2><p class="muted">后台执行，关闭页面不影响任务。可在任务中心取消；失败后由你决定是否重试。</p><div id="job-list"></div></section></div>`;renderJobs();$('#agent-form').onsubmit=e=>submit(e,async()=>{const fileIds=[...$('#agent-materials').selectedOptions].map(v=>v.value);if(fileIds.length>5)throw new Error('最多选择 5 份材料');await api('/jobs',{type:'agent',text:$('#agent-text').value,requirements:$('#agent-requirements').value,projectId:$('#agent-project').value,fileIds,idempotencyKey:crypto.randomUUID()});$('#agent-form').reset();formSnapshots.set($('#agent-form'),formSnapshot($('#agent-form')));await refresh();renderJobs();notify('智能任务已加入队列');});return;}
if(view==='tasks'){target.innerHTML=`<div class="grid"><section class="card"><h2>创建处理任务</h2><form id="task-form"><label for="task-type">任务类型</label><select id="task-type"><option value="polish">学术润色${cap.ai?'':'（AI 未配置）'}</option><option value="review">导师意见修改${cap.ai?'':'（AI 未配置）'}</option><option value="compare">用户材料查重（不检索全网）</option></select><label for="task-project">所属项目</label><select id="task-project">${optionProjects()}</select><label for="task-text">原文（AI 最多 6,000 字符，材料查重最多 8,000）</label><textarea id="task-text" required maxlength="8000"></textarea><label for="requirements">修改要求 / 导师意见（可选）</label><textarea id="requirements" maxlength="2000"></textarea><div id="sources-form" hidden><label for="source-title">实际来源标题</label><input id="source-title" maxlength="200"><label for="source-text">实际来源正文</label><textarea id="source-text" maxlength="8000"></textarea><label for="source-url">来源 URL（可选）</label><input id="source-url" type="url"><label for="source-doi">DOI（可选，未核验）</label><input id="source-doi" maxlength="200"><label for="source-authors">作者（可选）</label><input id="source-authors" maxlength="100"><label for="source-year">年份（可选）</label><input id="source-year" pattern="[0-9]{4}" maxlength="4"></div><p class="muted" id="task-note"></p><div class="actions"><button class="primary" id="task-submit">提交任务</button></div></form></section><section class="card"><h2>任务队列</h2><p class="muted">状态来自账户任务记录，处理中会自动更新。关闭页面不会停止已提交任务。重试 AI 任务可能产生额外的模型服务费用。</p><div id="job-list"></div></section></div>`;const change=()=>{const compare=$('#task-type').value==='compare';$('#task-text').maxLength=compare?8000:6000;$('#sources-form').hidden=!compare;$('#source-title').required=compare;$('#source-text').required=compare;$('#task-submit').disabled=!compare&&!cap.ai;$('#task-note').textContent=compare?'仅比较实际输入材料；相似度由确定性文本算法计算，不提供语义分数或全网检测结论。':cap.ai?`正文和要求将发送至 ${cap.aiProvider}。修改结果需人工确认，不保证检测分数。`:'需要配置模型接口后才能提交，不会返回模拟改写。';};$('#task-type').onchange=change;change();renderJobs();$('#task-form').onsubmit=e=>submit(e,async()=>{const type=$('#task-type').value;await api('/jobs',{type,text:$('#task-text').value,requirements:$('#requirements').value,projectId:$('#task-project').value,title:'用户材料查重',sources:type==='compare'?[{title:$('#source-title').value,text:$('#source-text').value,url:$('#source-url').value,doi:$('#source-doi').value,authors:$('#source-authors').value?[$('#source-authors').value]:[],year:$('#source-year').value}]:undefined,idempotencyKey:crypto.randomUUID()});$('#task-form').reset();change();formSnapshots.set($('#task-form'),formSnapshot($('#task-form')));jobs=(await api('/jobs')).items;renderJobs();notify('任务已提交');});return;}
if(view==='results'){target.innerHTML=`<section class="card"><h2>账户成果</h2>${resultRows()}</section><div id="result-detail"></div>`;wireResults();return;}
if(view==='usage'){const data=await api('/usage');target.innerHTML=`<section class="card"><h2>模型用量</h2><p class="muted">仅记录成功调用且服务实际返回的 Token 数，缺失字段显示未知。当前未启用扣费，不代表会员额度；第三方模型接口可能按自己的规则收费。</p>${data.items.map(v=>`<div class="row"><span>${esc(v.model)} · ${date(v.created_at)}</span><span>输入 ${v.input_tokens??'未知'} / 输出 ${v.output_tokens??'未知'}</span></div>`).join('')||'<p>还没有真实模型调用记录</p>'}</section>`;return;}
if(view==='membership'){const data=await api('/payments/entitlements');target.innerHTML=`<section class="card"><h2>已购权益</h2><p class="muted">仅展示已经核验支付的账户购买记录；具体服务范围以购买时的说明为准。</p>${data.items.length?data.items.map(p=>`<article class="card"><div class="row"><b>${esc(p.title)}</b><span class="tag">${Date.parse(p.expires_at)>Date.now()?(Date.parse(p.starts_at)>Date.now()?'待生效':'有效'):'已到期'}</span></div><p>${esc(p.description||'')}</p><p class="muted">生效时间：${date(p.starts_at)} · 到期时间：${date(p.expires_at)}</p><a href="#membership/pay?order=${encodeURIComponent(p.order_id)}">查看对应订单 →</a></article>`).join(''):'<div class="account-empty"><p>还没有已购权益。已付款后，权益会在服务器确认后记录到这里。</p></div>'}<div class="actions"><a class="button" href="/workspace.html#membership/pay">查看可购服务</a><a href="/workspace.html#orders">我的订单</a></div></section>`;return;}
if(view==='help'){const data=await api('/feedback');target.innerHTML=`<div class="grid"><section class="card"><h2>提交反馈</h2><form id="feedback-form"><label for="feedback">问题或建议</label><textarea id="feedback" required maxlength="3000"></textarea><p class="muted">反馈保存在你的 PaperKnow 账户中，请勿填写密码或验证码。</p><button class="primary">保存反馈</button></form></section><section class="card"><h2>我的反馈记录</h2>${data.items.map(v=>`<div class="row"><span>${esc(v.body)}<br><small>${date(v.created_at)}</small></span></div>`).join('')||'<p>暂无反馈</p>'}</section></div>`;$('#feedback-form').onsubmit=e=>submit(e,async()=>{await api('/feedback',{text:$('#feedback').value});await render();notify('反馈已提交');});return;}
}
async function submit(e,fn){e.preventDefault();if(busy)return;const button=e.submitter||e.currentTarget.querySelector('button[type=submit],button:not([type])');busy=true;if(button)button.disabled=true;try{await fn();}catch(err){if(alive&&err.name!=='AbortError')notify(err.message);}finally{busy=false;if(button?.isConnected)button.disabled=button.id==='task-submit'&&$('#task-type')?.value!=='compare'&&!cap.ai;}}
function renderJobs(){const target=$('#job-list');if(!target)return;target.innerHTML=jobs.slice(0,20).map(j=>`<div class="row"><span><b>${esc(({parse:'正文解析',polish:'学术润色',review:'导师意见修改',compare:'材料查重',agent:'科研智能助手'}[j.type]||j.type))}</b><br><small>${date(j.created_at)} · 第 ${j.attempt} 次执行</small>${j.error?`<p class="error">${esc(j.error)}</p>`:''}<div class="actions">${j.result_id?`<button data-result="${j.result_id}">查看成果</button>`:''}${['queued','running'].includes(j.status)?`<button data-job="${j.id}" data-action="cancel">取消任务</button>`:''}${j.status==='failed'?`<button data-job="${j.id}" data-action="retry">重试</button>`:''}</div></span><span class="tag ${j.status}">${statuses[j.status]}</span></div>`).join('')||'<p class="muted">暂无任务</p>';$all('[data-job]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{if(b.dataset.action==='retry'&&!await ask('重新执行可能重复调用模型并产生第三方费用，是否继续？'))return;await api(`/jobs/${b.dataset.job}/${b.dataset.action}`,{});jobs=(await api('/jobs')).items;renderJobs();}catch(err){notify(err.message);}finally{b.disabled=false;}});wireResults();}
function wireResults(){$all('[data-result]').forEach(b=>b.onclick=()=>showResult(b.dataset.result).catch(err=>notify(err.message)));}
async function showResult(id){if(dirty()&&!await ask('当前输入未提交，打开成果会丢弃输入。是否继续？'))return;const request=++resultRequest;const item=(await api('/results/'+encodeURIComponent(id))).item;if(request!==resultRequest)return;if(view!=='results'){rememberForms(true);go('results',{result:id});return;}results=(await api('/results')).items;await render();if(!alive||request!==resultRequest)return;ctx.resultOpened?.(id);const b=item.body;const target=$('#result-detail');if(!target)return;let content='';let exportText='';if(item.type==='parse'){exportText=b.text;content=`<p class="muted">${esc(b.fileName)} · ${b.characters} 字符 · ${esc(b.scope)}</p><pre>${esc(b.text)}</pre>`;}else if(item.type==='compare'){exportText=JSON.stringify(b,null,2);content=`<div class="banner">${esc(b.scope)}。语义分析未接入。来源信息由用户提供，未核验。</div><h2>文本相似度 ${(b.ratio*100).toFixed(1)}% · 去除已识别引用 ${(b.uncitedRatio*100).toFixed(1)}%</h2><p>${b.totalChars} 字 · 相似 ${b.similarChars} 字 · 命中 ${b.sourceCount} 份材料</p><p class="muted">${esc(b.citationPolicy)}</p>${b.sections.map(s=>`<section class="source"><h2>${esc(s.title)} · ${(s.ratio*100).toFixed(1)}%</h2>${s.paragraphs.map(p=>`<details><summary>${p.similarChars?'发现相似片段':'未发现相似片段'} · ${p.totalChars} 字</summary><pre>${esc(p.text)}</pre>${p.matches.map(m=>{const source=b.sources.find(v=>v.id===m.sourceId);return `<div class="compare"><pre><b>原文片段</b>\n${esc(Array.from(p.text).slice(...m.range).join(''))}</pre><pre><b>${esc(source.title)}</b>\n${esc(Array.from(source.text).slice(...m.sourceRange).join(''))}\n文本相似度：${m.textScore*100}%\n语义相似度：未计算\n引用状态：${m.citationStatus==='verified_quotation'?'已识别引用':'需人工核对'}\n作者：${esc(source.authors.join('、')||'未填写')} · 年份：${esc(source.year||'未填写')}\nDOI：${esc(source.doi||'未填写')}\n来源：用户材料${/^https?:\/\//i.test(source.url||'')?`\n<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">查看来源网页</a>`:''}</pre></div>`;}).join('')}</details>`).join('')}</section>`).join('')}`;}else{const versions=(await api(`/results/${id}/revisions`)).items;exportText=versions[0]?.body||b.suggestion;content=`<p class="muted">模型 ${esc(b.model)} · 结果需人工核对 · 原件与模型结果保留不变</p>${item.type==='agent'?`<details><summary>本次材料与工具记录</summary><p>${(b.materials||[]).map(m=>esc(m.name)).join('、')||'未选择原件'}</p>${(b.trace||[]).map(v=>`<p>${esc(v.tool)} · ${esc(v.status)}</p>`).join('')||'<p>本次未调用材料工具</p>'}</details>`:''}<div class="compare"><section><h2>${item.type==='agent'?'任务说明':'原文'}</h2><pre>${esc(b.original)}</pre></section><section><h2>${item.type==='agent'?'智能任务结果 / 你的编辑稿':'修改建议 / 你的编辑稿'}</h2><form id="revision-form"><textarea id="revision-text" maxlength="100000" required>${esc(exportText)}</textarea><div class="actions"><button class="primary">保存新版本</button><button type="button" id="original-suggestion">恢复模型建议到编辑区</button></div></form></section></div><h2>已保存版本</h2>${versions.map(v=>`<details><summary>${date(v.created_at)}</summary><pre>${esc(v.body)}</pre></details>`).join('')||'<p>尚无编辑版本</p>'}`;}
if(!alive||request!==resultRequest)return;target.innerHTML=`<section class="card detail"><h1>${esc(item.title)}</h1><div class="actions"><button id="export-result">导出成果</button></div>${content}</section>`;$('#export-result').onclick=()=>{const text=item.type==='compare'?exportText:item.type==='parse'?b.text:$('#revision-text').value;const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=item.type==='compare'?'材料查重报告.json':'PaperKnow成果.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};if($('#revision-form')){$('#original-suggestion').onclick=async()=>{if(await ask('替换当前编辑区为原始模型建议？已保存版本仍保留。'))$('#revision-text').value=b.suggestion;};$('#revision-form').onsubmit=e=>submit(e,async()=>{await api(`/results/${id}/revisions`,{text:$('#revision-text').value});formSnapshots.set($('#revision-form'),formSnapshot($('#revision-form')));await showResult(id);notify('新版本已保存');});}rememberForms();target.scrollIntoView?.({behavior:'smooth',block:'start'});}

 try{
  cap=await api('/capabilities');
  if(ctx.session){const state=await ctx.session();if(!alive)return;if(!state.user){if(state.status==='error')throw new Error('账户连接暂不可用');renderLogin();return;}user=state.user;}
  else user=(await api('/auth/me')).user;
  await refresh();if(!alive)return;await render();poll();
  if(view==='results'&&params.get('result'))await showResult(params.get('result'));
 }catch(error){if(!alive||error.name==='AbortError'||error.status===401)return;$('#view').innerHTML=`<section class="card account-login-required"><span class="account-empty-symbol">${icon('clock',26)}</span><h2>暂时无法读取账户内容</h2><p>请检查网络后重试。保存在此浏览器的本地内容仍可使用。</p><button id="online-retry" type="button">重新读取</button></section>`;$('#online-retry').onclick=()=>mountOnlineWorkspace(root,view,ctx,params);notify(error.message);}
 return instance;
}
